        const g = x.createLinearGradient(gx0, gy0, dx ? gx1 : gx0, dy ? gy1 : gy0); g.addColorStop(0, 'rgba(18,18,24,.55)'); g.addColorStop(1, 'rgba(18,18,24,0)');
