      x.globalAlpha = .18; x.fillStyle = '#4a4644'; x.beginPath(); x.ellipse((jx - X0m) * PPM, (jy - Y0m) * PPM, jr * .7 * PPM, jr * .7 * PPM, 0, 0, 6.3); x.fill(); x.globalAlpha = 1;
