    pesce: { sign: 'PESCHERIA', c: ['#2a5aa8', '#f4ead6'], crates: [['fish', 'fish', 'mussel'], ['fish', 'mussel', 'fish']], ice: true },
    forno: { sign: 'PANE', c: ['#c8862a', '#f4ead6'], crates: [['loaf', 'croissant', 'bread'], ['loaf-baguette', 'cheese', 'loaf']], ground: 'barrel' },
