    const g = x.createLinearGradient(0, gb * .55, 0, gb); g.addColorStop(0, 'rgba(20,15,30,0)'); g.addColorStop(1, 'rgba(20,15,30,.3)'); x.fillStyle = g; x.fillRect(0, 0, cw, gb);
