    for (let y = 0; y < 32; y += 8) for (let k = 0; k < 32; k += 8) { x.fillStyle = NEVE ? pick(r, ['#dce0e6', '#d2d6de', '#e4e8ee', '#c0c4cc']) : pick(r, ['#58565c', '#504e54', '#5e5c60', '#4a484e']); x.fillRect(k, y, 7, 7); }
