    if (r() < .6) { x.fillStyle = 'rgba(40,36,34,.35)'; x.fillRect(Math.floor(r() * 20), Math.floor(r() * 20), 8 + Math.floor(r() * 6), 6 + Math.floor(r() * 6)); }
