    const pp = cyl(.07, .07, 1.3, 6, sl('#2a2624')); pp.position.set(cx + (r() - .5) * (w - 1), base + H1 + .8, cz + (r() - .5) * (d - 1)); grp.add(pp); const ph = cyl(.12, .1, .12, 6, sl('#2a2624')); ph.position.set(pp.position.x, pp.position.y + .7, pp.position.z); grp.add(ph);
