          const g = new THREE.Group(), damaged = r() < .35, rustAll = r() < .4, parapet = run.some(q => q.wall);
          if (!parapet) { GR1.push(run.slice()); run = []; return; }   // [strade1] il guardrail lo costruisce buildGuardrail1
