      for (let py = 0; py < S; py++) for (let px = 0; px < S; px++) { const n1 = vnz(px / 9, py / 9) + vnz(px / 3, py / 3) * .5, o = (py * S + px) * 4, b = 128 + n1 * 26; d[o] = b + 6; d[o + 1] = b * .82; d[o + 2] = b * .6; d[o + 3] = 255; }
