      for (let i = 0; i < 60; i++) { g.fillStyle = pick(r, ['#5a4632', '#463626', '#9a8c78']); g.fillRect(Math.floor(r() * S), Math.floor(r() * S), 2, 1 + (r() < .4 ? 1 : 0)); }   // sassi
