    x.fillStyle = '#0a0b10'; x.fillRect(4, 0, 24, H); x.fillStyle = col; x.fillRect(4, 0, 2, H); x.fillRect(26, 0, 2, H);
    x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillStyle = col;
